"use strict";(self.webpackChunkkiwi_wiki=self.webpackChunkkiwi_wiki||[]).push([["91482"],{73786(e,t,n){n.r(t),n.d(t,{assets:()=>l,contentTitle:()=>r,default:()=>c,frontMatter:()=>o,metadata:()=>i,toc:()=>h});var i=n(6446),s=n(74848),a=n(28453);let o={title:"Ladders and Their Accessories",date:new Date("2020-11-27T00:00:00.000Z"),tags:["V2ray","VPN","Old-Blog"],slug:"2020/11/27-01",description:"Still more V2Ray-related information"},r,l={authorsImageUrls:[]},h=[{value:"VLESS",id:"vless",level:2},{value:"Motivation",id:"motivation",level:3},{value:"Differences",id:"differences",level:3},{value:"Testing Platform",id:"testing-platform",level:3},{value:"Server-Side Thoughts",id:"server-side-thoughts",level:3},{value:"Client-Side Thoughts",id:"client-side-thoughts",level:3},{value:"Gateway V2ray client",id:"gateway-v2ray-client",level:5},{value:"Linux Client - QV2Ray+V2ray",id:"linux-client---qv2rayv2ray",level:5},{value:"Android Client - V2RayNG",id:"android-client---v2rayng",level:5},{value:"Pros (Very Subjective)",id:"pros-very-subjective",level:6},{value:"Cons",id:"cons",level:6},{value:"Conclusion",id:"conclusion",level:2}];function d(e){let t={admonition:"admonition",code:"code",del:"del",h2:"h2",h3:"h3",h5:"h5",h6:"h6",li:"li",p:"p",strong:"strong",ul:"ul",...(0,a.R)(),...e.components};return(0,s.jsxs)(s.Fragment,{children:[(0,s.jsx)(t.admonition,{type:"info",children:(0,s.jsx)(t.p,{children:'This article was automatically translated by Google "Gemini". The author does not guarantee its accuracy or wording.'})}),"\n",(0,s.jsx)(t.admonition,{type:"info",children:(0,s.jsx)(t.p,{children:"This article was reposted from the old site archive."})}),"\n",(0,s.jsxs)(t.p,{children:["The day before yesterday, I picked up another cheap VPS from ",(0,s.jsx)(t.strong,{children:"RackNerd"}),"'s Thanksgiving sale\u2014getting two years of usage for around 18 USD."]}),"\n",(0,s.jsx)(t.h2,{id:"vless",children:"VLESS"}),"\n",(0,s.jsx)(t.p,{children:"I mainly bought this one to test out VLESS configuration and usage, so as soon as I got it, I went straight to setting up VLESS. As usual, the detailed installation notes will go into the Wiki, so I won't specifically go into the installation and setup details here\u2014let's just talk about my initial impressions."}),"\n",(0,s.jsx)(t.h3,{id:"motivation",children:"Motivation"}),"\n",(0,s.jsx)(t.p,{children:"Even though I know VLESS was created because VMess has issues that make it 100% detectable, the \"ladders\" (proxies) I currently have all use the WS+TLS architecture, so they aren't actually that risky (and if that's considered risky, wouldn't VLESS be just as risky?). So it wasn't strictly necessary to switch to VLESS. Still, after seeing some recommendations from Chinese users saying VLESS performs much better (since removing all the encryption and authentication from the original VMess should theoretically make it faster),"}),"\n",(0,s.jsx)(t.p,{children:"I couldn't resist... (a classic example of impulse buying)."}),"\n",(0,s.jsx)(t.h3,{id:"differences",children:"Differences"}),"\n",(0,s.jsx)(t.p,{children:"When using VMess+WS+TLS, to save myself the trouble, I basically always recommended using Caddy to handle the WS+TLS part. However, with VLESS, because TLS has to be wrapped inside V2Ray itself, you need to specify the path to the SSL key. That turns Caddy's convenient automatic SSL certificate handling into a bit of an issue (actually it shouldn't really be a problem\u2014it's just that because it's automatic, you still have to track down where it stores its keys and verify it yourself). On top of that, Caddy v2's configuration file became more complex compared to v1, and I'm not as familiar with its configuration logic and documentation as I am with Nginx or Apache (at the end of the day, it still comes down to my own limitations...)."}),"\n",(0,s.jsx)(t.h3,{id:"testing-platform",children:"Testing Platform"}),"\n",(0,s.jsx)(t.p,{children:"Because Caddy was no longer needed, thanks to my bizarre habit, I naturally wanted to reinstall the entire OS instead of just uninstalling packages (I guess to some extent this is a bad habit spoiled by VMs\u2014whenever I'm too lazy to make big changes, I just reinstall). So at first I started working on the Arch Linux machine at home that runs my backup V2Ray. Since I was also rewriting my Arch Linux automated install script recently, I got carried away and started debugging the script while reinstalling the system at the same time (speaking of which, I have to say it's really annoying that the installation process changed slightly again, forcing me to rewrite core parts of the script...). So the day before yesterday, most of my time was spent tweaking the script and reinstalling the OS..."}),"\n",(0,s.jsx)(t.p,{children:"Later, when I got the RackNerd VPS, I took the opportunity to deploy directly on it. These VPS providers basically only offer Debian/Ubuntu or CentOS-based distros, and none of the Arch Linux I like to use..."}),"\n",(0,s.jsxs)(t.p,{children:["After looking at some tutorials online, I felt using Arch Linux might actually be simpler\u2014at the very least, ",(0,s.jsx)(t.code,{children:"pacman"})," can handle the installation without needing to run an external script, and you don't need to edit ",(0,s.jsx)(t.code,{children:"crontab"})," for auto-updates (speaking of which, auto-updates on my other VPSes basically all broke because the install script path changed)."]}),"\n",(0,s.jsx)(t.h3,{id:"server-side-thoughts",children:"Server-Side Thoughts"}),"\n",(0,s.jsx)(t.p,{children:"Because V2Ray can handle the WS+TLS part by itself, I initially thought naively that I wouldn't need to install Nginx or Apache during setup. However, thinking about it afterward, it's still easier to handle SSL keys with Certbot if a web server is installed, so I installed one anyway..."}),"\n",(0,s.jsx)(t.p,{children:"Overall, though, the fact that once V2Ray is configured you can run WebSocket without even starting Nginx/Apache is pretty convenient\u2014it saves you from configuring an extra web server. That said, in the end you probably still need to set up the web server anyway, otherwise its fallback won't work properly."}),"\n",(0,s.jsx)(t.p,{children:"You can see this trend aligns with the V2Ray team's vision: from the beginning, V2Ray never intended to be just a SOCKS server. What they want is more like a comprehensive, extensible network management Swiss Army knife\u2014with DNS, routing tables, communication protocols, encryption, and so on. If one day it includes a full web server module rather than just WS functionality, I probably wouldn't be surprised at all."}),"\n",(0,s.jsx)(t.p,{children:"Right now it's set up with VLESS+WS+TLS in the most minimal way following a template. Once the XTLS licensing issue is sorted out later, I might also try VLESS+XTLS to see if it's really as powerful as people say (everyone says it's as fast as running unencrypted...)."}),"\n",(0,s.jsx)(t.h3,{id:"client-side-thoughts",children:"Client-Side Thoughts"}),"\n",(0,s.jsx)(t.h5,{id:"gateway-v2ray-client",children:"Gateway V2ray client"}),"\n",(0,s.jsx)(t.p,{children:"Yep, I switched my room's Gateway over to the VPS running VLESS+WS+TLS. It seems to work pretty normally. As for speed, it's probably bottlenecked by China Unicom's terrible network, so I can't tell at all whether it got faster... (so basically, my original goal wasn't achieved at all\u2014well, comparing speed and efficiency without a decent network route is kind of a joke anyway, right??)"}),"\n",(0,s.jsx)(t.p,{children:"Right now I'm basically doing stability testing to see if there are any surprises over the next few days (hopefully pleasant ones, not scary ones)."}),"\n",(0,s.jsx)(t.h5,{id:"linux-client---qv2rayv2ray",children:"Linux Client - QV2Ray+V2ray"}),"\n",(0,s.jsx)(t.p,{children:"Because my Linux Desktop (the one I'm writing this blog post on right now) runs Manjaro, installing V2Ray is super easy, which makes me very grateful to the Arch team."}),"\n",(0,s.jsx)(t.p,{children:"As for how it feels to use... well, I can only say I only tried it for a short moment before stopping, mainly because there's currently no WiFi at the office to connect to (so this post probably won't be published on time on the day I wrote it)."}),"\n",(0,s.jsx)(t.p,{children:"However, it seemed to perform about the same as the Gateway\u2014no noticeable difference, probably still bottlenecked by the network route."}),"\n",(0,s.jsx)(t.h5,{id:"android-client---v2rayng",children:"Android Client - V2RayNG"}),"\n",(0,s.jsxs)(t.p,{children:["Since there aren't many clients that support VLESS yet, I had no choice but to newly install ",(0,s.jsx)(t.strong,{children:"V2RayNG"})," on my phone. I have to say, it feels more stable and nicer to use than ",(0,s.jsx)(t.strong,{children:"BifrostV"}),"\u2014honestly, this app is the main reason I wanted to write this post (wait, so everything before this was just filler?!)."]}),"\n",(0,s.jsx)(t.h6,{id:"pros-very-subjective",children:"Pros (Very Subjective)"}),"\n",(0,s.jsxs)(t.ul,{children:["\n",(0,s.jsxs)(t.li,{children:["\n",(0,s.jsx)(t.p,{children:"QR code / barcode compatible with QV2Ray"}),"\n",(0,s.jsxs)(t.p,{children:["First, this app supports the same barcode format as ",(0,s.jsx)(t.strong,{children:"Qv2ray"}),', which follows the "standard specification." Compared to ',(0,s.jsx)(t.strong,{children:"BifrostV"}),", which uses its own proprietary format, this is much more convenient to use. That said, it's not that ",(0,s.jsx)(t.strong,{children:"BifrostV"})," was being stubborn, rather that there wasn't a clearly defined V2Ray link barcode standard earlier\u2014but either way, being able to use the same barcode format is definitely much nicer."]}),"\n"]}),"\n",(0,s.jsxs)(t.li,{children:["\n",(0,s.jsx)(t.p,{children:"No ads, and a GUI to my taste"}),"\n",(0,s.jsx)(t.p,{children:"Although I'm not completely opposed to free apps having ads, having a clean app without unnecessary ads really makes you feel happy."}),"\n",(0,s.jsxs)(t.p,{children:["Maybe it's because the ",(0,s.jsx)(t.strong,{children:"Shadowsocks"})," app left such a good impression on me earlier\u2014its clean GUI style, responsiveness, and being the first app that let me reliably climb over the wall\u2014that I have a really high affinity for ",(0,s.jsx)(t.strong,{children:"V2RayNG"}),"'s interface, which looks a lot like ",(0,s.jsx)(t.strong,{children:"shadowsocks"}),"."]}),"\n"]}),"\n",(0,s.jsxs)(t.li,{children:["\n",(0,s.jsx)(t.p,{children:"Fast response and high stability"}),"\n",(0,s.jsxs)(t.p,{children:["When I first switched to ",(0,s.jsx)(t.strong,{children:"BifrostV"})," for V2Ray, I often felt its responsiveness and stability weren't as good as ",(0,s.jsx)(t.strong,{children:"shadowsocks"}),"\u2014it would frequently hang upon opening, or randomly disconnect mid-session, and things like that. At the time, though, I felt there wasn't any other alternative that covered so many protocols, so I just put up with it\u2014until I switched to ",(0,s.jsx)(t.strong,{children:"V2RayNG"})," for VLESS, and everything changed..."]}),"\n",(0,s.jsxs)(t.p,{children:["It brought back that feeling of using ",(0,s.jsx)(t.strong,{children:"shadowsocks"})," again. Though honestly, since I rarely wander around outside, I don't actually rely on proxy apps on my phone or tablet all that heavily\u2014and once I'm back in my room, the WiFi is already behind a Gateway that handles the proxy, so I basically don't need to proxy again on the device..."]}),"\n"]}),"\n"]}),"\n",(0,s.jsx)(t.h6,{id:"cons",children:"Cons"}),"\n",(0,s.jsxs)(t.ul,{children:["\n",(0,s.jsxs)(t.li,{children:["\n",(0,s.jsx)(t.p,{children:"DNS issues"}),"\n",(0,s.jsxs)(t.p,{children:["I'm not sure whether it's a VLESS issue or a ",(0,s.jsx)(t.strong,{children:"V2RayNG"})," issue, but it doesn't handle DNS poisoning very well. With the exact same settings, connecting to VMess+WS+TLS works completely fine, but as soon as I connect to VLESS+WS+TLS, DNS errors occur and I can't connect. After randomly trying things out, only the following settings worked properly:"]}),"\n",(0,s.jsxs)(t.ul,{children:["\n",(0,s.jsxs)(t.li,{children:["Domain Strategy - Either ",(0,s.jsx)(t.code,{children:"IPIfNonMatch"})," or ",(0,s.jsx)(t.code,{children:"IPOnDemand"})," works"]}),"\n",(0,s.jsx)(t.li,{children:"Predefined Rules - Bypass LAN and Mainland China"}),"\n",(0,s.jsx)(t.li,{children:"Enable Local DNS - Must NOT be enabled"}),"\n",(0,s.jsxs)(t.li,{children:["Remote DNS - Change to Google's ",(0,s.jsx)(t.code,{children:"8.8.8.8"})]}),"\n"]}),"\n",(0,s.jsx)(t.p,{children:"That's how it is for now, though logically there shouldn't be an issue. Maybe once I figure out what's causing it later, I'll come back and update this."}),"\n"]}),"\n"]}),"\n",(0,s.jsx)(t.h2,{id:"conclusion",children:"Conclusion"}),"\n",(0,s.jsxs)(t.p,{children:["In short, proxy-related tech is probably something that only people living in ",(0,s.jsx)(t.del,{children:"the Great Power"})," the Celestial Empire ever bother learning. Just like my master said, \"That's a very niche skill tree\u2014among this group, probably only you who's stationed over there would put points into it.\" So I could only dig through online resources, pick up a little superficial knowledge, and embarrass myself by sharing it here."]}),"\n",(0,s.jsx)(t.p,{children:"Fortunately, there are still plenty of resourceful folks in the Celestial Empire, so related info is still easy to find\u2014well, yes... it's easy to find once you've scaled the wall and can use Google, whereas inside the wall you can't find a single article..."}),"\n",(0,s.jsx)(t.p,{children:'So when it comes down to it, a "ladder" is really just something where you need a tool to get over the wall the first time. Once you have that, building any other ladder afterward is relatively easy...'}),"\n",(0,s.jsx)(t.p,{children:"That said, building ladders is inherently a small act of defiance against the Celestial Empire's state apparatus\u2014it requires constant updates and refinement. If you truly want a permanent solution once and for all,"}),"\n",(0,s.jsx)(t.p,{children:'physically getting yourself out ("emigrating in person") is still the most practical option.'})]})}function c(e={}){let{wrapper:t}={...(0,a.R)(),...e.components};return t?(0,s.jsx)(t,{...e,children:(0,s.jsx)(d,{...e})}):d(e)}},28453(e,t,n){n.d(t,{R:()=>o,x:()=>r});var i=n(96540);let s={},a=i.createContext(s);function o(e){let t=i.useContext(a);return i.useMemo(function(){return"function"==typeof e?e(t):{...t,...e}},[t,e])}function r(e){let t;return t=e.disableParentContext?"function"==typeof e.components?e.components(s):e.components||s:o(e.components),i.createElement(a.Provider,{value:t},e.children)}},6446(e){e.exports=JSON.parse('{"permalink":"/en/2020/11/27-01","source":"@site/i18n/en/docusaurus-plugin-content-blog/b-2020-11-27-01.md","title":"Ladders and Their Accessories","description":"Still more V2Ray-related information","date":"2020-11-27T00:00:00.000Z","tags":[{"inline":true,"label":"V2ray","permalink":"/en/tags/v-2-ray"},{"inline":true,"label":"VPN","permalink":"/en/tags/vpn"},{"inline":true,"label":"Old-Blog","permalink":"/en/tags/old-blog"}],"readingTime":8.34,"hasTruncateMarker":true,"authors":[],"frontMatter":{"title":"Ladders and Their Accessories","date":"2020-11-27T00:00:00.000Z","tags":["V2ray","VPN","Old-Blog"],"slug":"2020/11/27-01","description":"Still more V2Ray-related information"},"unlisted":false,"prevItem":{"title":"The Ladder, Part II...","permalink":"/en/2020/12/01-01"},"nextItem":{"title":"Note taking tools","permalink":"/en/2020/11/16-01"}}')}}]);